mapper.sql:
r.wms_tenant_id = #{wmsTenantId}
AND r.fee_type = 'SHIPPING'

    AND r.bill_month >= #{monthStart}


    AND r.bill_month <= #{monthEnd}


    AND r.erp_tenant_id IN
    #{e}

mapper.select:
SELECT b.bill_month AS billMonth, COALESCE(SUM(b.total_amount), 0) AS amount
FROM wms_monthly_bill b

    b.deleted = 0
    AND b.wms_tenant_id = #{wmsTenantId}

        AND b.bill_month >= #{monthStart}


        AND b.bill_month <= #{monthEnd}


GROUP BY b.bill_month

SELECT o.erp_tenant_id AS erpTenantId,
       t.tenant_name AS ownerName,
       COUNT(*) AS orders
FROM wms_sales_outbound_order o
INNER JOIN sys_tenant t ON t.id = o.erp_tenant_id AND t.parent_wms_tenant_id = #{wmsTenantId}

    o.order_status <> 'CANCELLED'

        AND o.outbound_date >= #{dateStart}


        AND o.outbound_date <= #{dateEnd}


        AND o.erp_tenant_id IN
        #{e}


GROUP BY o.erp_tenant_id, t.tenant_name
ORDER BY orders DESC
LIMIT 10

SELECT COUNT(*) AS cnt, COALESCE(SUM(monthly_fee), 0) AS fee
FROM wms_rack_assignment
WHERE wms_tenant_id = #{wmsTenantId}
  AND effective_from <= #{today}
  AND (effective_to IS NULL OR effective_to >= #{today})
